import{_ as r,r as a,o as c,c as p,e as o,a as e,s as i,d as n}from"./chunks/framework.CXcwiNg-.js";const k=JSON.parse('{"title":"Ошибки и журналирование - October CMS - 3.x","titleTemplate":false,"description":"Находите ошибки и другие записи журнала о вашем сайте.","frontmatter":{"subtitle":"Находите ошибки и другие записи журнала о вашем сайте."},"headers":[{"level":2,"title":"Конфигурация","slug":"конфигурация","link":"#конфигурация","children":[{"level":4,"title":"Детализация ошибок","slug":"детализация-ошибок","link":"#детализация-ошибок","children":[]},{"level":4,"title":"Режимы файлов журнала","slug":"режимы-фаилов-журнала","link":"#режимы-фаилов-журнала","children":[]},{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/setup/errors-logging.md","filePath":"3.x/ru/setup/errors-logging.md"}'),d={name:"3.x/ru/setup/errors-logging.md"};function g(u,s,h,f,m,_){const t=a("pre-heading"),l=a("post-heading");return c(),p("div",null,[o(t),s[0]||(s[0]=e("h1",null,"Ошибки и журналирование",-1)),o(l),s[1]||(s[1]=i(`<p>Когда вы начинаете использовать October CMS, обработка ошибок и исключений уже настроена для вас. Существует два способа доступа к журналу событий:</p><ol><li>Журнал событий можно просмотреть в файловой системе, открыв файл <code>storage/logs/system.log</code>.</li><li>Также его можно просмотреть через панель администратора, перейдя в раздел <strong>Настройки → Журнал событий</strong>.</li></ol><p>Записи в журнале всегда создаются при отображении страницы ошибки и для определённых <a href="./../extend/system/exceptions.html">типов исключений</a>.</p><h2 id="конфигурация"><a href="#конфигурация" class="header-anchor">#</a> Конфигурация</h2><h4 id="детализация-ошибок"><a href="#детализация-ошибок" class="header-anchor">#</a> Детализация ошибок</h4><p>Степень детализации ошибок, отображаемых вашим приложением в браузере, определяется параметром конфигурации <code>debug</code> в файле <code>config/app.php</code>. По умолчанию детальный вывод ошибок <em>включён</em>, что полезно для просмотра подробной информации об ошибках при отладке и устранении неполадок. Когда эта функция отключена, при возникновении проблемы на странице будет отображаться общее сообщение об ошибке.</p><p>Для локальной разработки следует установить значение <code>debug</code> в <code>true</code>. В рабочем окружении это значение всегда должно быть <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/*
|--------------------------------------------------------------------------
| Application Debug Mode
|--------------------------------------------------------------------------
|
| When your application is in debug mode, detailed error messages with
| stack traces will be shown on every error that occurs within your
| application. If disabled, a simple generic error page is shown.
|
*/</span>

<span class="token string single-quoted-string">&#39;debug&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
</code></pre></div><h4 id="режимы-фаилов-журнала"><a href="#режимы-фаилов-журнала" class="header-anchor">#</a> Режимы файлов журнала</h4><p>October CMS поддерживает различные драйверы, включая режимы журналирования <code>single</code>, <code>daily</code>, <code>syslog</code> и <code>errorlog</code>. Например, если вы хотите использовать ежедневные файлы журнала вместо одного файла, просто установите значение <code>default</code> в файле конфигурации <code>config/logging.php</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;LOG_CHANNEL&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;daily&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4>`,12)),s[2]||(s[2]=e("div",{class:"custom-block also"},[e("ul",null,[e("li",null,[e("a",{href:"https://laravel.com/docs/10.x/logging",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Документация Laravel по журналированию"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),e("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const x=r(d,[["render",g]]);export{k as __pageData,x as default};
